-- Passage rg12-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('03e6d0f6-e71c-5fe6-899b-f266f515aef5', 'rg12-character-setting-plot-p02', (select id from public.skills where slug = 'read-g12-character-setting-plot'), null,
        '9-12', $q$Third Leg$q$, $q$The rain came in sideways off the parking lot
and turned the far curve of the track into a mirror.
I stood in my lane with my hand stretched back,
counting the marks I had chalked that morning, now gone.

Last spring I dropped the baton in this same zone.
I still hear the sound it made, a hollow tick,
louder than the whole grandstand going quiet.
Coach never mentioned it. That was worse.

So all summer I practiced the handoff in my driveway,
my little brother running at me with a paper towel tube,
over and over until the streetlights came on
and our neighbor stopped pretending not to watch.

Now Desmond is coming, splashing, his face all teeth,
and the chalk is gone, and I have to guess.
I start too early. I know I start too early.
I slow down, which you are never supposed to do,
and I hold my hand perfectly still behind me.

He slaps the baton into my palm like a promise.
I do not look down. I do not need to look.
The water throws my reflection up beside me,
and for one whole curve there are two of us running.$q$, 'draft')
